import React, { Suspense, useEffect } from 'react';
import './App.css';
import { BrowserRouter as Router, Routes, Route, useParams, Link as RouterLink } from 'react-router-dom';
import { Link, CircularProgress, Box } from '@mui/material';
import Homepage from './Homepage';
import Blog from './Blog';

const NotebookViewer = React.lazy(() =>
  import('notebook-renderer/library').then((module) => {
    import('notebook-renderer/NotebookViewer.css');
    return { default: module.NotebookViewer };
  }),
);

const RESUME_PDF_PATH = 'https://docs.google.com/document/d/1qhT4JxxFUdAOfkZKIKEdxQ_EyjMvRPhMe0PjkeTEJZ8/export?format=pdf';

let notebooksManifest = null;
try {
  // eslint-disable-next-line import/no-unresolved
  notebooksManifest = require('./notebooks-manifest.json');
} catch (error) {
  console.warn('Notebooks manifest not found. Run "npm run generate-notebooks-manifest" to generate it.');
}

const ResumeRedirect = () => {
  useEffect(() => {
    window.history.replaceState(null, '', '/');
    window.location.assign(RESUME_PDF_PATH);
  }, []);
  return (
    <div style={{ padding: 24, fontFamily: 'system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif' }}>
      <div style={{ maxWidth: 720, margin: '0 auto' }}>
        <h2 style={{ margin: 0, marginBottom: 12, fontWeight: 700 }}>Opening resume…</h2>
        <p style={{ marginTop: 0, marginBottom: 12, color: '#444' }}>
          If it doesn’t open automatically, use the link below.
        </p>
        <p style={{ marginTop: 0, marginBottom: 24 }}>
          <a href={RESUME_PDF_PATH} target="_blank" rel="noreferrer">
            Open resume PDF
          </a>
        </p>
        <p style={{ margin: 0 }}>
          <a href="/">Back to homepage</a>
        </p>
      </div>
    </div>
  );
};

const NotebookViewerRoute = () => {
  const { notebookPath } = useParams();
  const decodedPath = notebookPath ? decodeURIComponent(notebookPath) : '';
  const fullPath = decodedPath ? `/notebooks/${decodedPath}` : null;
  const notebookFromManifest = decodedPath
    && notebooksManifest?.notebooks?.find((nb) => nb.filename === decodedPath);

  return (
    <Suspense
      fallback={(
        <Box sx={{ py: 8, textAlign: 'center' }}>
          <CircularProgress />
        </Box>
      )}
    >
      <NotebookViewer
        notebookPath={fullPath}
        title={notebookFromManifest?.title}
        backLink={(
          <Link
            component={RouterLink}
            to="/blog"
            sx={{
              position: 'absolute',
              top: 16,
              left: 16,
              color: '#1e40af',
              textDecoration: 'none',
              fontFamily: "'Source Serif 4', serif",
              fontSize: '1rem',
              '&:hover': { textDecoration: 'underline' },
            }}
          >
            ← Blog
          </Link>
        )}
      />
    </Suspense>
  );
};

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          <Route path="/" element={<Homepage />} />
          <Route path="/portfolio" element={<ResumeRedirect />} />
          <Route path="/resume" element={<ResumeRedirect />} />
          <Route path="/blog" element={<Blog />} />
          <Route path="/notebook/:notebookPath" element={<NotebookViewerRoute />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
